// Build a readable alert from the failed execution that n8n passes to an Error Trigger.
const input = $input.first().json;

const workflow = input.workflow || {};
const execution = input.execution || {};
const error = execution.error || {};
const failedNode = error.node || {};

const wfName = workflow.name || 'unknown workflow';
const nodeName = failedNode.name || execution.lastNodeExecuted || 'unknown node';
const errMsg = error.message || error.description || 'unknown error';
const execUrl = execution.url || null;

const lines = [
  '\u{1F534} n8n workflow failed',
  '',
  'Workflow: ' + wfName,
  'Failed node: ' + nodeName,
  'Error: ' + errMsg,
  'Run mode: ' + (execution.mode || 'unknown'),
  'Started: ' + (execution.startedAt || execution.createdAt || 'unknown'),
  'Execution: ' + (execUrl || '(open Executions in n8n)'),
];

return [{
  json: {
    severity: 'error',
    workflow: wfName,
    failedNode: nodeName,
    errorMessage: errMsg,
    mode: execution.mode || null,
    executionUrl: execUrl,
    message: lines.join('\n'),
  },
}];
